function badge(status){const value=String(status||'unknown'),p=E('span',value.replaceAll('_',' '),'pill');if(/^[a-z_]+$/.test(value))p.classList.add(value);return p;}
function note(text){return E('div',text,'capability-note');}
function link(text,href,cls='text-link'){const e=E('a',text,cls);e.href=href;return e;}
function btn(text,action,cls='secondary',glyph){const b=E('button',undefined,cls);b.type='button';if(glyph)b.append(icon(glyph));b.append(E('span',text));b.addEventListener('click',async()=>{b.disabled=true;try{await action();}catch(e){notice(e.message,true);}finally{b.disabled=false;}});return b;}
function notice(text,error=false){$('#notice').hidden=!text;$('#notice').textContent=text;$('#notice').classList.toggle('error',error);}
async function api(path,body){const r=await fetch(path,body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});if(r.status===401){location.assign('/login');throw Error('Sign in to continue.');}const d=await r.json();if(!r.ok)throw Error(d.error_description||d.error||'Could not complete this operation.');return d;}
async function tool(name,args={}){return api('/api/tool',{name,arguments:args});}
async function change(name,args,success){const r=await tool(name,args);await refresh(true);if(success)notice(success);return r;}
function empty(title,text,action){const e=E('div',undefined,'empty-state');e.append(icon('folder'),E('h2',title),E('p',text));if(action)e.append(action);return e;}
function panel(title,subtitle,action){const box=E('section',undefined,'panel'),head=E('div',undefined,'section-top'),copy=E('div');copy.append(E('h2',title));if(subtitle)copy.append(E('p',subtitle));head.append(copy);if(action)head.append(action);box.append(head);return box;}
function heading(title,description,actions=[]){$('#header-description').textContent=description;$('#page-title').textContent=title;$('#page-description').textContent=description;$('#page-actions').replaceChildren(...actions);}
function setTheme(value){document.documentElement.dataset.theme=value;try{localStorage.setItem('vso-theme',value);}catch{}themeIcon();if(routeName()==='setup')render();}
function themeIcon(){const dark=document.documentElement.dataset.theme==='dark';$('#theme-toggle').replaceChildren(icon(dark?'sun':'moon'));$('#theme-toggle').setAttribute('aria-label','Switch to '+(dark?'light':'dark')+' theme');$('#theme-toggle').setAttribute('aria-pressed',String(dark));}
function routeName(){return location.hash.slice(1).split('/')[0]||(location.pathname==='/onboarding'?'setup':'home');}
function navigate(){const hash=location.hash.slice(1).split('/'),id=hash[0]||routeName();projectId=hash[1]||'';if(!titles[id]&&!['project','unassigned'].includes(id)){location.hash='home';return;}document.body.classList.remove('nav-open');$('#nav-backdrop').hidden=true;$('#mobile-nav').setAttribute('aria-expanded','false');for(const a of $('#main-nav').querySelectorAll('a')){const active=a.hash==='#'+id||(a.hash==='#projects'&&['project','unassigned','productions'].includes(id));a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');}projectTab='all';if(data)render();window.scrollTo({top:0,behavior:'instant'});}
async function refresh(force=false){if(refreshing){if(!force)return;await refreshDone;return refresh(true);}refreshing=true;refreshDone=new Promise(resolve=>{finishRefresh=resolve;});try{const [control,legacy,library]=await Promise.all([api('/api/control'),api('/api/state'),tool('template_catalog').catch(error=>({templates:[],categories:[],selections:[],features:[],error:error.message}))]);templatesData=library;data=control;state=legacy;const owner=legacy.onboarding.profile;const name=owner?.brand||owner?.name||'Your workspace';$('#workspace-name').textContent=name;$('#top-name').textContent=name;$('#owner-avatar').textContent=$('#top-avatar').textContent=name[0].toUpperCase();$('#instance-host').textContent=location.hostname;$('#version').textContent=$('#footer-version').textContent=data.version;$('#live-state').textContent='Live · '+age(data.observed_at);const count=$('#project-nav-count');if(count)count.textContent=data.projects.length;const playing=[...document.querySelectorAll('video')].some(v=>!v.paused);const editing=['INPUT','TEXTAREA','SELECT','BUTTON','A'].includes(document.activeElement.tagName)||$('#connect-dialog').open;const frame=$('#flow-frame');if(force||firstLoad||(!editing&&!playing&&!frame)){render();firstLoad=false;}}catch(e){notice(e.message,true);$('#live-state').textContent='Refresh unavailable';if(!data)$('#page-root').replaceChildren(empty('Workspace could not load',e.message,btn('Try again',()=>refresh(true),'primary')));}finally{refreshing=false;finishRefresh();}}
function metrics(){const r=E('div',undefined,'metrics');const scheduled=state.publication.filter(p=>p.status==='scheduled');for(const [label,value,sub,glyph,href]of[['Observed credits',num(data.credits.total_observed),data.credits.observed_accounts+' Flow profiles','chart','#accounts'],['Projects',num(data.projects.length),state.asset.length+' media files','folder','#projects'],['Scheduled',num(scheduled.length),'Approved releases','calendar','#schedule'],['Connected accounts',num(data.connected_identities.length),'Social destinations','connect','#accounts']]){const m=E('a',undefined,'metric');m.href=href;const mark=E('span',undefined,'metric-mark');mark.append(icon(glyph));const copy=E('div',undefined,'metric-copy');copy.append(E('span',label,'metric-label'),E('strong',value),E('small',sub));m.append(copy,mark);r.append(m);}return r;}

function chart(samples,key='memory_percent'){const ns='http://www.w3.org/2000/svg',svg=document.createElementNS(ns,'svg');svg.setAttribute('viewBox','0 0 600 120');svg.setAttribute('class','chart');svg.setAttribute('role','img');svg.setAttribute('aria-label','Observed memory utilization over time. '+samples.length+' recorded samples.');for(const y of [15,60,105]){const line=document.createElementNS(ns,'path');line.setAttribute('d',`M0 ${y}H600`);line.setAttribute('class','chart-grid');svg.append(line);}const rows=samples.filter(s=>s[key]!=null);if(rows.length){const pts=rows.map((s,i)=>[rows.length>1?i/(rows.length-1)*600:300,110-s[key]]);const line=document.createElementNS(ns,'path');line.setAttribute('d',pts.map((p,i)=>(i?'L':'M')+p.join(' ')).join(' '));line.setAttribute('class','chart-line');if(pts.length>1){const area=document.createElementNS(ns,'path');area.setAttribute('d','M'+pts[0][0]+' 120 '+pts.map(p=>'L'+p.join(' ')).join(' ')+' L'+pts.at(-1)[0]+' 120Z');area.setAttribute('class','chart-area');svg.append(area);}svg.append(line);const dot=document.createElementNS(ns,'circle');dot.setAttribute('cx',pts.at(-1)[0]);dot.setAttribute('cy',pts.at(-1)[1]);dot.setAttribute('r','3.5');dot.setAttribute('fill','currentColor');svg.append(dot);}return svg;}
function resourcePanel(){const r=data.resources,p=panel('Server performance','Observed host resources',link('View system →','#system'));const readings=E('div',undefined,'resource-top');for(const [label,value,sub]of[['CPU',pct(r.cpu_percent),r.cpu_count+' logical CPUs'],['Memory',pct(r.memory_percent),bytes(r.memory_used)+' / '+bytes(r.memory_total)],['Storage',pct(r.disk_percent),bytes(r.disk_used)+' / '+bytes(r.disk_total)]]){const e=E('div',undefined,'resource-reading');e.append(E('span',label),E('strong',value),E('small',sub));readings.append(e);}p.append(readings,chart(r.history));const foot=E('div',undefined,'chart-note');foot.append(E('span','Memory · '+(r.history.length>1?'recorded samples':'history starts now')),E('span','Updated '+age(r.at)));p.append(foot);return p;}
function roleCard(role){const c=E('article',undefined,'role-card'+(role.status==='running'?' active':'')),top=E('div',undefined,'role-top');top.append(E('span',role.initials,'role-avatar'),badge(role.status));c.append(top,E('h3',role.name),E('p',role.active[0]?.label||role.latest?.label||role.description),E('small',role.latest?(role.latest.status==='running'?'Working now':age(role.latest.ended_at||role.latest.started_at))+' · '+role.today+' calls / 24h':'No observed work yet'));return c;}
