function creditsPanel(){const p=panel('Flow balances','Last observed, never estimated',btn('Refresh',async()=>{notice('Reading existing Flow profiles…');const r=await tool('control_refresh_accounts');await refresh(true);notice(r.accounts.filter(a=>a.status==='refreshed').length+' account balances refreshed.');},'text-link'));const total=E('div',undefined,'credit-total');total.append(E('strong',num(data.credits.total_observed)),E('small','observed credits'));p.append(total);for(const a of data.accounts.filter(a=>a.provider==='flow')){const row=E('div',undefined,'list-row'),copy=E('div',undefined,'row-copy');copy.append(E('b',a.name||a.label),E('small',a.credits==null?'Balance unknown':age(a.verified_at)));row.append(accountMark(a),copy,E('span',a.credits==null?'—':num(a.credits),'value'));p.append(row);}if(!data.credits.total_accounts)p.append(empty('No Flow accounts','Connect your own Google profiles to observe balances.',link('Connect accounts →','#accounts')));p.append(E('p',data.credits.unknown_accounts+' unknown balances excluded. Refresh to check current availability.','credit-foot'));return p;}
