function queuePanel(){const p=panel('Up next','Planned content and approved releases',link('Calendar →','#schedule'));const list=data.schedules.filter(s=>s.at>Date.now()/1000-3600&&!['cancelled','missed','published','failed'].includes(s.status)).slice(0,3);for(const item of list){const row=E('div',undefined,'list-row'),d=E('span',undefined,'queue-date');d.append(E('strong',new Date(item.at*1000).getDate()),E('span',new Intl.DateTimeFormat(undefined,{month:'short'}).format(new Date(item.at*1000))));const copy=E('div',undefined,'row-copy');copy.append(link(item.name,item.project_id?'#project/'+item.project_id:'#publishing'),E('small',item.destination+' · '+time(item.at)),badge(item.kind==='scheduled'?'scheduled':item.status));row.append(d,copy);p.append(row);}if(!list.length)p.append(empty('Room for your next release','Planned projects and approved upload times will appear here.',link('Browse projects →','#projects')));return p;}
