function productionPulsePanel(){const box=panel('Production activity','Job requests over the last seven days',link('View activity →','#activity'));const days=[];for(let i=6;i>=0;i--){const day=new Date();day.setHours(0,0,0,0);day.setDate(day.getDate()-i);const start=day.getTime()/1000,end=start+86400,rows=data.jobs.filter(j=>(j.created_at||0)>=start&&(j.created_at||0)<end);days.push({day,total:rows.length,completed:rows.filter(j=>j.status==='completed').length});}const total=days.reduce((a,d)=>a+d.total,0),top=E('div',undefined,'production-total');top.append(E('strong',num(total)),E('span','job requests'));box.append(top);const bars=E('div',undefined,'production-bars'),max=Math.max(1,...days.map(d=>d.total));for(const d of days){const column=E('div',undefined,'production-bar-column'),track=E('div',undefined,'production-bar-track'),fill=E('div',undefined,'production-bar-fill');fill.style.height=(d.total/max*100)+'%';track.append(fill);column.append(E('b',d.total?num(d.total):'—'),track,E('small',new Intl.DateTimeFormat(undefined,{weekday:'short'}).format(d.day)));bars.append(column);}box.append(bars);const legend=E('p',total?'Counted from saved job requests. Completion and usable outputs are reviewed separately.':'No job requests recorded in this period. Start a production in ChatGPT.','chart-note');box.append(legend);return box;}

