function projectPage(root){const p=data.projects.find(p=>p.id===projectId);if(!p){heading('Project not found','This production may belong to another installation.');root.append(empty('Project unavailable','Return to your own project collection.',link('Browse projects →','#projects','secondary')));return;}heading(p.name,data.channels.find(c=>c.id===p.channel_id)?.name||'Independent video production',[btn('Organize media',()=>{location.hash='unassigned';},'secondary'),btn('Edit project',()=>editProject(p),'primary')]);root.append(link('← All projects','#projects','text-link project-back'));const saved=templatesData?.selections.filter(x=>x.project_id===p.id)||[];if(saved.length){const choices=panel('Saved creative direction','Selected looks for ChatGPT · does not approve generation');for(const selection of saved){const row=E('div',undefined,'list-row'),copy=E('div',undefined,'row-copy');copy.append(E('b',templatesData.templates.find(t=>t.id===selection.template_id)?.title||selection.template_id),E('small',selection.subject),E('small',(selection.shots?.length||1)+' shot prompts · '+selection.settings.aspect_ratio),btn('Read saved prompts',()=>savedRecipeDialog(selection),'text-link'));row.append(copy,badge('selected_for_host'));choices.append(row);}root.append(choices);}root.append(link('Choose a video recipe →','#templates','text-link project-template'));const info=E('div',undefined,'project-info section-gap');info.append(badge(p.status),E('span',p.image_count+' images'),E('span',p.clip_count+' videos'),E('span','Created '+date(p.created_at)));if(p.planned_for)info.append(E('span','Planned '+date(new Date(p.planned_for).getTime()/1000)));root.append(info);const tabs=E('div',undefined,'tabs');for(const [id,label]of[['all','Overview'],['storyboard','Images'],['clip','Scene clips'],['final','Final exports'],['script','Script & direction'],['releases','Releases']])tabs.append(btn(label,()=>{projectTab=id;render();},projectTab===id?'selected':''));root.append(tabs);
 if(projectTab==='script'){if(!p.plan){root.append(note('This project has no saved script yet. Ask ChatGPT to prepare and save its concepts and scene direction.'));return;}concepts(root,p);return;}
 if(projectTab==='releases'){releaseList(root,p.publications);return;}
 if(projectTab==='all')root.append(productionSteps(p));if(p.plan)reviewActions(root,p);
 let assets=p.assets;if(projectTab==='storyboard')assets=assets.filter(a=>['storyboard','image','reference'].includes(a.category));else if(projectTab==='clip')assets=assets.filter(a=>a.category==='clip');else if(projectTab==='final')assets=assets.filter(a=>a.category==='final');const seen=new Set;assets=assets.filter(a=>{if(seen.has(a.id+':'+a.category+':'+a.scene))return false;seen.add(a.id+':'+a.category+':'+a.scene);return true;});if(projectTab==='all'){appendMediaGroups(root,assets);}else{const grid=E('div',undefined,'media-grid');assets.forEach(a=>grid.append(assetCard(a)));root.append(assets.length?grid:empty('No '+(projectTab==='storyboard'?'images':projectTab==='final'?'final exports':'scene clips')+' yet','Attach assets from ChatGPT or organize existing files into this project.',link('Open unassigned media →','#unassigned','secondary')));}if(p.jobs.length){const box=panel('Production jobs','Original requests and their observed status');p.jobs.forEach(j=>{const row=E('div',undefined,'list-row'),copy=E('div',undefined,'row-copy');copy.append(E('b',(j.scene>=0?'Scene '+(j.scene+1)+' · ':'')+(j.model||j.job_kind.replaceAll('-',' '))),E('small',j.error||'Created '+date(j.created_at)));row.append(icon('film'),copy,badge(j.status));box.append(row);});box.classList.add('section-gap');root.append(box);}}
function productionSteps(p){const row=E('div',undefined,'production-stepper');const has=(kind)=>p.assets.some(a=>a.category===kind);const current=p.publications.some(x=>x.status==='published')?4:has('final')?3:has('clip')?2:p.image_count?1:0;['Concept','Images','Scene clips','Final export','Release'].forEach((label,i)=>{const step=E('div',undefined,'production-step'+(i===current?' current':''));step.append(E('span',i+1),E('b',label));row.append(step);});return row;}
