function templateDialog(t){
 const root=modal(t.title,t.description);$('#connect-dialog').classList.add('recipe-dialog');const requirements=E('div',undefined,'recipe-requirements');requirements.append(E('h3','Reference images you need'));t.reference_requirements.forEach(x=>requirements.append(E('p',x)));root.append(requirements,note(t.pitfalls));const original=E('details',undefined,'recipe-original');original.open=true;original.append(E('summary','Complete recipe prompt'),E('pre',t.video_prompt,'prompt-preview'));root.append(original);
 const requestId=crypto.randomUUID();let compiled=null,signature='',edited=false;const {f,finish}=modalForm(root,'Save to project',async values=>{const current=JSON.stringify([values.get('subject'),values.get('continuity'),values.get('aspect_ratio'),values.get('duration_seconds'),values.get('dialogue')]);if(compiled&&current!==signature&&edited)throw Error('Your subject/settings changed. Personalize prompts again before saving edits.');if(!compiled||current!==signature)await personalize();let pid=values.get('project_id');if(!pid){const name=values.get('new_project').trim();if(!name)throw Error('Name a new project or choose one.');pid=(await tool('project_create',{name,request_id:'template-project-'+requestId})).id;}const video_prompts=[...f.querySelectorAll('.recipe-video-prompt')].map(x=>x.value);return tool('template_select',{project_id:pid,template_id:t.id,subject:values.get('subject'),continuity:values.get('continuity'),settings:{aspect_ratio:values.get('aspect_ratio'),duration_seconds:Number(values.get('duration_seconds')),dialogue:values.get('dialogue'),video_prompts},request_id:requestId});},()=>notice('Full prompts saved to the project. Ask ChatGPT to use this exact recipe direction.'));
 const project=field(f,'Project','project_id','select');project.append(new Option('Create a new project',''));data.projects.forEach(p=>project.append(new Option(p.name,p.id)));const name=field(f,'New project name','new_project');name.maxLength=160;name.placeholder=t.title+' video';name.required=true;project.onchange=()=>{name.required=!project.value;name.closest('label').hidden=Boolean(project.value);};
 const subject=field(f,'Your subject and setting','subject');subject.required=true;subject.maxLength=4000;subject.placeholder='Describe the exact person, product or scene references.';const lock=field(f,'Continuity locks (optional)','continuity');lock.maxLength=4000;lock.placeholder='Exact face, outfit, product count, room or light to preserve.';
 const frame=field(f,'Frame','aspect_ratio','select');['9:16','16:9','1:1','4:3','3:4','21:9'].forEach(x=>frame.append(new Option(x,x)));const seconds=field(f,'Suggested seconds per shot','duration_seconds','number','8');seconds.min=4;seconds.max=30;const dialogue=field(f,'Exact short dialogue (optional)','dialogue');dialogue.maxLength=500;dialogue.placeholder='Leave blank for the recipe’s ambient audio plan.';
 f.append(E('p','Clip length, reference/end-frame support and native speech must match the actual model. Multi-shot formats are separate generations, then an edit.','form-note'));
 const editors=E('div',undefined,'recipe-shot-editors');
 async function personalize(){if(!subject.reportValidity()||!seconds.reportValidity())throw Error('Complete the subject and suggested duration.');const values=new FormData(f);compiled=await tool('template_compile',{template_id:t.id,subject:values.get('subject'),continuity:values.get('continuity'),settings:{aspect_ratio:values.get('aspect_ratio'),duration_seconds:Number(values.get('duration_seconds')),dialogue:values.get('dialogue')}});signature=JSON.stringify([values.get('subject'),values.get('continuity'),values.get('aspect_ratio'),values.get('duration_seconds'),values.get('dialogue')]);edited=false;editors.replaceChildren();for(const shot of compiled.shots){const box=E('section',undefined,'recipe-shot-editor');box.append(E('h3','Shot '+(shot.index+1)+' · '+shot.title));const ref=E('details');ref.append(E('summary','First-frame image prompt'),E('pre',shot.image_prompt,'prompt-preview'));box.append(ref);const label=E('label','Video prompt · editable'),input=E('textarea',undefined,'recipe-video-prompt');input.name='video_prompt_'+shot.index;input.value=shot.video_prompt;input.rows=10;input.required=true;input.maxLength=12000;input.oninput=()=>{edited=true;};label.append(input);box.append(label,btn('Copy shot '+(shot.index+1),async()=>{await navigator.clipboard.writeText(input.value);notice('Video prompt copied.');},'text-link'));editors.append(box);}original.open=false;}
 f.append(btn('Personalize prompts',personalize,'secondary'),editors);finish();
}
function learningPanel(root){const box=panel('Content memory & learning','Save the work, observe the result, choose one better test.');box.classList.add('section-gap','learning-overview');const image=E('img',undefined,'learning-illustration');image.src='/brand/storyboard-desk.webp';image.alt='Photographic storyboard prints beside a lens and film reel';image.loading='lazy';image.width=1024;image.height=1536;const copy=E('div');copy.append(E('h3','Your channel’s history becomes its context.'),E('p','Each prepared release freezes its creative decisions. Official observations and owner-supplied insights stay separate. Early patterns remain hypotheses.'),E('p','Read-only checkpoints: 6h, 24h, 72h and 7 days, while this server is running. Missing retention and permissions are shown as unavailable.','muted'));const actions=E('div',undefined,'row-actions');for(const channel of data.channels)actions.append(btn('Open '+channel.name,()=>learningDialog(channel.id),'secondary'));if(!data.channels.length)actions.append(link('Create a channel brief →','#planning','text-link'));actions.append(btn('Research sources',researchSourcesDialog,'text-link'));copy.append(actions);const body=E('div',undefined,'learning-presentation');body.append(copy,image);box.append(body);root.append(box);}
async function learningDialog(channelId){const d=await tool('content_context',{channel_id:channelId});const root=modal(d.channel.name+' · content memory','Private history for this channel only. Counts and associations do not establish what caused an outcome.');const stats=E('div',undefined,'summary-grid');for(const [name,value]of [['Creative records',d.release_records.length],['Observations',d.observations.length],['Hypotheses',d.lessons.length]]){const c=E('div',undefined,'summary-block');c.append(E('span',name),E('strong',value));stats.append(c);}root.append(stats,note(d.next_step));const toggle=btn(d.policy.enabled?'Pause performance checks':'Enable read-only performance checks',async()=>{await tool('learning_policy',{enabled:!d.policy.enabled});$('#connect-dialog').close();await learningDialog(channelId);},'secondary');root.append(toggle,E('p','Enabling applies to this independent installation’s confirmed public releases. It never spends credits, posts content or starts a ChatGPT conversation.','form-note'));for(const r of d.release_records){const item=E('details',undefined,'memory-record');item.append(E('summary',r.release.title||r.publication_id),E('p',r.fields.hook||'Historical hook was not saved.','script-copy'));item.append(E('pre',r.fields.video_prompts?.join('\n\n')||'Historical video prompts are unavailable. They have not been reconstructed.','prompt-preview'));const observations=d.observations.filter(o=>o.publication_id===r.publication_id);for(const o of observations)item.append(E('p',Object.entries(o.metrics).map(([k,v])=>k.replaceAll('_',' ')+': '+num(v)).join(' · ')||'Provider returned no usable counts','memory-metrics'),E('small',o.source.type+' · '+age(o.observed_at)+' · '+(o.checkpoint_hours?o.checkpoint_hours+'h checkpoint':'baseline')+(o.comparable_age?'':' · not an age-matched comparison')));for(const c of d.comparisons.filter(c=>c.publication_id===r.publication_id))item.append(note(c.finding.replaceAll('_',' ')+' · '+c.peer_count+' comparable peers'+(c.views_multiple!==null?' · '+c.views_multiple+'× median':'')+' · descriptive, not causal'));root.append(item);}if(!d.release_records.length)root.append(E('p','No frozen releases for this channel yet. Save exact decisions before the next approved release.','muted section-gap'));for(const lesson of d.lessons){const item=panel('Hypothesis',lesson.confidence);item.append(E('p',lesson.claim),E('p','Next test: '+lesson.next_test));root.append(item);}}
async function researchSourcesDialog(){const d=await tool('research_sources');const root=modal('Research sources','Legitimate public services and owner-authorized APIs. No shared credentials ship.');root.append(note(d.policy));for(const source of d.sources){const row=E('section',undefined,'research-source');row.append(E('h3',source.name),E('small',source.category+' · '+source.auth+' · '+source.adapter),E('p',source.coverage),E('p',source.limits,'form-note'),link('Official documentation ↗',source.docs));root.append(row);}}

function render(){if(!data)return;const id=routeName(),root=$('#page-root');root.replaceChildren();root.className='animate-in';document.body.dataset.page=id;$('#breadcrumb-page').textContent=id==='home'?'Overview':id==='project'?'Projects':(titles[id]?.[0]||id);if(titles[id])heading(...titles[id]);if(id==='home')dashboard(root);else if(['projects','productions'].includes(id))projectsPage(root);else if(id==='media')mediaPage(root);else if(id==='templates')templatesPage(root);else if(id==='project')projectPage(root);else if(id==='unassigned')unassignedPage(root);else if(id==='schedule')schedulePage(root);else if(id==='agents')teamPage(root);else if(id==='activity')activityPage(root);else if(id==='analytics'){analyticsPage(root);learningPanel(root);}else if(id==='planning'){planningPage(root);learningPanel(root);}else if(id==='accounts'||id==='flow')accountsPage(root,id==='flow');else if(id==='system')systemPage(root);else if(id==='setup')settingsPage(root);else if(id==='publishing')publishingPage(root);}
function modal(title,description){const root=$('#dialog-content');$('#connect-dialog').classList.remove('lightbox-dialog','recipe-dialog');root.replaceChildren(E('h2',title),E('p',description));$('#connect-dialog').showModal();return root;}
function field(form,label,name,type='text',value=''){const l=E('label',label),i=E(type==='select'?'select':'input');i.name=name;if(type!=='select')i.type=type;if(value)i.value=value;l.append(i);form.append(l);return i;}
function modalForm(root,save,handler,after){const f=E('form'),error=E('p','','form-error');error.setAttribute('role','alert');const submit=E('button',save,'primary');submit.type='submit';f.addEventListener('submit',async event=>{event.preventDefault();submit.disabled=true;try{const result=await handler(new FormData(f));await refresh(true);$('#connect-dialog').close();if(after)await after(result);}catch(e){error.textContent=e.message;}finally{submit.disabled=false;}});root.append(f);return {f,finish:()=>f.append(error,submit)};}
function createProject(){const r=modal('A home for your next video','Give this production a name. Images, scene clips and exports will live together.'),{f,finish}=modalForm(r,'Create project',async values=>{const p=await tool('project_create',{name:values.get('name'),channel_id:values.get('channel_id'),planned_for:values.get('planned_for')?new Date(values.get('planned_for')).toISOString():'',request_id:crypto.randomUUID()});location.hash='project/'+p.id;});const n=field(f,'Project name','name');n.required=true;n.maxLength=160;n.placeholder='A name you will recognize';const channel=field(f,'Channel (optional)','channel_id','select');channel.append(new Option('Independent production',''));data.channels.forEach(c=>channel.append(new Option(c.name,c.id)));field(f,'Editorial date (optional, does not schedule an upload)','planned_for','datetime-local');finish();}
function editProject(project){const r=modal('Edit project','An editorial date is a plan, not publication approval.'),{f,finish}=modalForm(r,'Save project',v=>tool('project_rename',{project_id:project.id,name:v.get('name'),planned_for:v.get('planned_for')?new Date(v.get('planned_for')).toISOString():''}));const name=field(f,'Project name','name','text',project.name);name.required=true;name.maxLength=160;const date=field(f,'Editorial date','planned_for','datetime-local');if(project.planned_for){const d=new Date(project.planned_for);date.value=new Date(d-d.getTimezoneOffset()*60000).toISOString().slice(0,16);}finish();}
function assignAsset(asset){if(!data.projects.length){createProject();return;}const r=modal('Assign to a video project','The original remains intact. Choose the production and scene where this asset belongs.'),{f,finish}=modalForm(r,'Assign asset',v=>tool('project_attach_asset',{project_id:v.get('project_id'),asset_id:asset.id,kind:v.get('kind'),scene:v.get('scene')?Number(v.get('scene'))-1:-1}));const project=field(f,'Project','project_id','select');data.projects.forEach(p=>project.append(new Option(p.name,p.id)));const kind=field(f,'Media type','kind','select');(asset.media_type.startsWith('video/')?['clip','final']:['storyboard','image','reference']).forEach(k=>kind.append(new Option(k,k)));const scene=field(f,'Scene number (optional)','scene','number');scene.min=1;scene.max=1000;finish();}
function openProviderSettings(provider){const dialog=$('#connect-dialog');if(dialog.open)dialog.close();const destination='#setup/'+provider;if(location.hash===destination)navigate();else location.hash=destination;}
function connectDialog(){const r=modal('Connect your accounts','Sign into official providers. Each account belongs to this installation.');for(const [provider,name]of[['flow','Google Flow profile'],['youtube','YouTube'],['instagram','Instagram'],['facebook','Facebook Pages']]){r.append(btn(name,async()=>{if(provider==='flow'){addFlow();return;}try{const result=await tool('account_start',{provider,label:name});location.assign(result.url);}catch(e){r.append(note(e.message),btn('Configure '+name,()=>openProviderSettings(provider),'secondary','connect'));}},'secondary'));}}
function addFlow(){const r=modal('Add Google profile','A dedicated profile keeps this account on your server. You enter the password and 2FA directly into Google.'),{f,finish}=modalForm(r,'Open Google sign-in',values=>tool('flow_account_add',{label:values.get('label')}),async a=>{location.hash='flow';await new Promise(requestAnimationFrame);await openBrowser(a);});const n=field(f,'Profile label','label');n.required=true;finish();}
for(const [id,label,glyph,group]of nav){if(group)$('#main-nav').append(E('p',group,'nav-label'));const a=link('', '#'+id);a.setAttribute('aria-label',label);a.title=label;a.dataset.label=label;a.append(icon(glyph),E('span',label));if(id==='projects'){const count=E('span','0','nav-count');count.id='project-nav-count';a.append(count);}$('#main-nav').append(a);}
$('#mobile-nav').append(icon('menu'));$('#refresh').append(icon('refresh'));$('#search-icon').append(icon('search'));themeIcon();$('#theme-toggle').onclick=()=>setTheme(document.documentElement.dataset.theme==='dark'?'light':'dark');$('#refresh').onclick=()=>refresh(true);$('#logout').onclick=async()=>{try{await api('/api/logout',{});location.assign('/login');}catch(e){notice(e.message,true);}};
function closeNav(){document.body.classList.remove('nav-open');$('#nav-backdrop').hidden=true;$('#mobile-nav').setAttribute('aria-expanded','false');}
$('#sidebar').addEventListener('click',event=>{if(event.target.closest('a'))closeNav();});
$('#mobile-nav').onclick=()=>{const open=document.body.classList.toggle('nav-open');$('#nav-backdrop').hidden=!open;$('#mobile-nav').setAttribute('aria-expanded',String(open));};$('#nav-backdrop').onclick=closeNav;$('#dialog-close').onclick=()=>$('#connect-dialog').close();$('#connect-dialog').onclick=e=>{if(e.target===$('#connect-dialog'))$('#connect-dialog').close();};window.addEventListener('hashchange',navigate);document.addEventListener('keydown',e=>{if(e.key==='Escape')closeNav();if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)){e.preventDefault();$('#global-search').focus();}});$('#global-search').addEventListener('input',event=>{filter=event.target.value.toLowerCase();if(routeName()==='templates'){templateQuery=filter;render();return;}if(!['projects','media','accounts','flow'].includes(routeName()))location.hash='projects';else render();});document.addEventListener('visibilitychange',()=>{if(!document.hidden)refresh();});setInterval(()=>{if(!document.hidden)refresh();},15000);navigate();refresh();
